	/*
     * @param	event CreateInsuredObjectEvent
     */
    @EventHandler( payloadType=CreateInsuredObjectEvent.class )
    public void handle( CreateInsuredObjectEvent event) {
	    LOGGER.info("handling CreateInsuredObjectEvent - " + event );
	    InsuredObject entity = new InsuredObject();
            entity.setInsuredObjectId( event.getInsuredObjectId() );
            entity.setDescription( event.getDescription() );
            entity.setSerialOrId( event.getSerialOrId() );
            entity.setPrimaryAddress( event.getPrimaryAddress() );
            entity.setObjectType( event.getObjectType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInsuredObject( entity );
    }

    /*
     * @param	event UpdateInsuredObjectEvent
     */
    @EventHandler( payloadType=UpdateInsuredObjectEvent.class )
    public void handle( UpdateInsuredObjectEvent event) {
    	LOGGER.info("handling UpdateInsuredObjectEvent - " + event );
    	
	    InsuredObject entity = new InsuredObject();
            entity.setInsuredObjectId( event.getInsuredObjectId() );
            entity.setDescription( event.getDescription() );
            entity.setSerialOrId( event.getSerialOrId() );
            entity.setPrimaryAddress( event.getPrimaryAddress() );
            entity.setPolicy( event.getPolicy() );
            entity.setCoverages( event.getCoverages() );
            entity.setObjectType( event.getObjectType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindInsuredObject( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInsuredObject( entity );        
    }
    
