    /**
     * Method to retrieve the InsuredObject via an InsuredObjectPrimaryKey.
     * @param 	id Long
     * @return 	InsuredObject
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public InsuredObject handle( FindInsuredObjectQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getInsuredObjectId() );
    }
    
    /**
     * Method to retrieve a collection of all InsuredObjects
     *
     * @param	query	FindAllInsuredObjectQuery 
     * @return 	List<InsuredObject> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<InsuredObject> handle( FindAllInsuredObjectQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindInsuredObject,
 * but only if the id matches
 *
 * @param		entity	InsuredObject
 */
	protected void emitFindInsuredObject( InsuredObject entity ) {
		LOGGER.info("handling emitFindInsuredObject" );
		
	    queryUpdateEmitter.emit(FindInsuredObjectQuery.class,
	                            query -> query.getFilter().getInsuredObjectId().equals(entity.getInsuredObjectId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInsuredObject
	 * 
	 * @param		entity	InsuredObject
	 */
	protected void emitFindAllInsuredObject( InsuredObject entity ) {
		LOGGER.info("handling emitFindAllInsuredObject" );
		
	    queryUpdateEmitter.emit(FindAllInsuredObjectQuery.class,
	                            query -> true,
	                            entity);
	}

